def breadcrumb(nid):
    cur=nodes[nid]; parts=[]
    while cur:
        parts.append(cur['name'])
        if cur['parent_id'] is None: break
        cur=nodes[cur['parent_id']]
    return ' > '.join(([streams[nodes[nid]['stream_id']]] if nodes[nid]['stream_id'] in streams else [])+list(reversed(parts)))

