def credential(p):
    n=p['fullName'].lower(); lvl=p['programmeLevel']
    if lvl=='CERTIFICATE' or 'foundation course' in n: return 'certificate'
    if lvl=='DIPLOMA' or 'diploma' in n or 'd.el.ed' in n: return 'diploma'
    if lvl=='PG Diploma': return 'postgraduate diploma'
